function validate([nums, sequences]) {
  const n = nums.length;
  if (n < 1) return 'nums needs at least one value.';
  const position = new Array(n + 1).fill(-1);
  for (let i = 0; i < n; i++) {
    const v = nums[i];
    if (v < 1 || v > n || position[v] !== -1) return 'nums must hold each of 1 to n exactly once.';
    position[v] = i;
  }
  if (sequences.length < 1) return 'sequences needs at least one sequence.';
  const seen = new Set();
  for (const seq of sequences) {
    if (seq.length < 1) return 'Every sequence needs at least one value.';
    for (let j = 0; j < seq.length; j++) {
      if (seq[j] < 1 || seq[j] > n) return 'Sequence values are between 1 and n.';
      if (j > 0 && position[seq[j]] <= position[seq[j - 1]]) return 'Every sequence must be a subsequence of nums.';
    }
    const key = seq.join(',');
    if (seen.has(key)) return 'No two sequences may be equal.';
    seen.add(key);
  }
  return null;
}

