function sequenceReconstruction(nums, sequences) {
  const n = nums.length;
  const isSub = (small, big) => {
    let k = 0;
    for (const v of big) if (k < small.length && small[k] === v) k++;
    return k === small.length;
  };
  // A value missing from every sequence makes a shorter supersequence possible.
  const present = new Set(sequences.flat());
  if (present.size < n) return false;
  if (n <= 7) {
    // Small inputs: try every arrangement of 1..n and count those containing all sequences.
    let count = 0;
    const order = [];
    const used = new Array(n + 1).fill(false);
    const build = () => {
      if (order.length === n) {
        if (sequences.every(seq => isSub(seq, order))) count++;
        return;
      }
      for (let v = 1; v <= n; v++) {
        if (used[v]) continue;
        used[v] = true;
        order.push(v);
        build();
        order.pop();
        used[v] = false;
      }
    };
    build();
    return count === 1;
  }
  // Larger inputs: nums is forced exactly when each neighbouring pair of nums sits side by side in some sequence.
  const pairs = new Set();
  for (const seq of sequences) for (let i = 1; i < seq.length; i++) pairs.add(seq[i - 1] * 100000 + seq[i]);
  for (let i = 1; i < n; i++) if (!pairs.has(nums[i - 1] * 100000 + nums[i])) return false;
  return true;
}

