function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 2000 : 1 + pick(6);
  const nums = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = pick(i + 1);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  const sequences = [];
  const seen = new Set();
  const add = seq => {
    const key = seq.join(',');
    if (seq.length > 0 && !seen.has(key)) { seen.add(key); sequences.push(seq); }
  };
  // Half the time cover every neighbouring pair with overlapping chunks, possibly leaving one pair out.
  if (rand() < 0.5 && n > 1) {
    const step = 1 + pick(large ? 30 : 3);
    const skip = rand() < 0.5 ? pick(n - 1) : -1;
    for (let start = 0; start < n - 1; start += step) {
      const end = Math.min(start + step, n - 1);
      if (skip >= start && skip < end) {
        add(nums.slice(start, skip + 1));
        add(nums.slice(skip + 1, end + 1));
      } else {
        add(nums.slice(start, end + 1));
      }
    }
  }
  // Then add random subsequences of nums.
  const extra = large ? 150 + pick(100) : 1 + pick(4);
  for (let k = 0; k < extra; k++) {
    const keep = large ? 2 + pick(60) : 1 + pick(Math.max(1, n - 1));
    const chance = keep / n;
    const seq = nums.filter(() => rand() < chance);
    add(seq.length ? seq : [nums[pick(n)]]);
  }
  return [nums, sequences];
}
